SourceCode.Declaration:
/// <summary>
/// Extension of WMSJournalTable for weighing process
/// </summary>
[ExtensionOf(formstr(WMSJournalTable))]
internal final class AVARUMWMSJournalTableFrm_Extension
{
#TASK

}

Method.Source:
/// <summary>
/// Standard task.
/// </summary>
/// <param name = "_taskId">taskId</param>
/// <returns>taskId result</returns>
public int task(int _taskId)
{
    int ret;

    ret = next task(_taskId);        

    return ret;
}

/// <summary>
/// Creates a jounal line with purch details form AVARUMWeightInHistory and opens the journal
/// </summary>
/// <param name = "_journalId">JournalId of the header to use. Must be created before</param>
/// <param name = "_AVARUMWeightInHistory">The weighing record</param>
public void AVACreateAndOpen(Range _journalId, AVARUMWeightInHistory _AVARUMWeightInHistory)
{
    PurchLine locPurchLine;        
    locPurchLine=PurchLine::findRecId(_AVARUMWeightInHistory.OriginRefRecId);
    if (!locPurchLine)
    {
        throw error("@AVARUM:AVARUMWMSJournalTableMsg1");
    }

    // find header
    WMSJournalTable_ds.positionToRecordByValue(fieldNum(WMSJournalTable, JournalId), _journalId);
    if (WMSJournalTable.JournalId==_journalId)
    {
        // switch to Line edit mode
        this.task(#taskSwitchToDetailsView);
        this.task(#taskEditRecord);

        journalFormTrans.formInitPost();

        // create line
        WMSJournalTrans_ds.create();

        WMSJournalTrans.inventTransId=locPurchLine.InventTransId;
        journalFormTrans.fieldModifiedInventTransIdPost();           

        WMSJournalTrans.qty=_AVARUMWeightInHistory.Value;
        journalFormTrans.fieldModifiedQtyPost();

    }
    else
    {
        error("@SYS83964");
    }
}

/// <summary>
/// Check wheather to auto open/create journal if is called form menuitem AVARUMWMSJournalReceptionWeighing
/// </summary>
public void run()
{
    next run();        

    if (this.args().menuItemName()==identifierStr(AVARUMWMSJournalReceptionWeighing))
    {
        Container con=str2con(this.args().parm(), ';', false);
        RecId recid=str2Int64(conPeek(con, 2));
        Range journalId=conPeek(con, 1);

        AVARUMWeightInHistory locAVARUMWeightInHistory;
        select firstonly * from locAVARUMWeightInHistory
            where locAVARUMWeightInHistory.RecId==recid;

        if (!locAVARUMWeightInHistory
            || locAVARUMWeightInHistory.step!=AVARUMWeightInStep::Amount)
        {
            throw error("@AVARUM:AVARUMWMSJournalTableMsg1");
        }

        this.AVACreateAndOpen(journalId, locAVARUMWeightInHistory);
    }

}
